def load_config_file(config_file_path, config_file):
    """
    Loads a config file, whether it is a yaml file or a .INI file.

    :param config_file_path: Path of the configuration file, used to infer the file format.
    :returns: Dictionary representation of the configuration file.
    """
    if config_file_path.endswith(".yaml") or config_file_path.endswith(".yml"):
        with open(config_file_path, "r") as f:
            config = yaml.safe_load(f)
    elif config_file_path.endswith(".ini"):
        config = configparser.ConfigParser()
        config.read(config_file_path)
    else:
        raise Exception(
            "Unsupported file format. Supported file formats are .yaml and .ini."
        )

    # If the config file is a .ini file, it is converted to a dictionary.
    if isinstance(config, configparser.ConfigParser):
        config = {}
        for section in config.sections():
            config[section] = {}
            for key, value in config[section].items():
                config[section][key] = value

    return config

