def save_config_file(config_file_path, config_file):
    """
    Saves a config file, whether it is a yaml file or a .INI file.

    :param config_file_path: Path of the configuration file, used to infer the file format.
    :param config_file: Dictionary representation of the configuration file.
    """
    if config_file_path.endswith(".yaml") or config_file_path.endswith(".yml"):
        with open(config_file_path, "w") as f:
            yaml.safe_dump(config_file, f, default_flow_style=False)
    elif config_file_path.endswith(".ini"):
        config = configparser.ConfigParser()
        for section in config_file.keys():
            config[section] = {}
            for key, value in config_file[section].items():
                config[section][key] = value
        with open(config_file_path, "w") as f:
            config.write(f)
    else:
        raise Exception(
            "Unsupported file format. Supported file formats are .yaml and .ini."
        )


